import{_ as n,C as a,o as r,c as i,j as t,a as o,E as d,ao as h}from"./chunks/framework.DOMnz-Zz.js";const y=JSON.parse('{"title":"Work-state colours","description":"","frontmatter":{},"headers":[],"relativePath":"concepts/work-state.md","filePath":"concepts/work-state.md","lastUpdated":null}'),l={name:"concepts/work-state.md"};function c(u,e,g,p,m,w){const s=a("DemoShot");return r(),i("div",null,[e[0]||(e[0]=t("h1",{id:"Work-state-colours",tabindex:"-1"},[o("Work-state colours "),t("a",{class:"header-anchor",href:"#Work-state-colours","aria-label":'Permalink to "Work-state colours {#Work-state-colours}"'},"​")],-1)),e[1]||(e[1]=t("p",null,[o("With several agents running, the question is always the same: "),t("em",null,"which one needs me?"),o(" Ship of Tools answers it with colour. Every session row in Sessions mode and on the bottom session strip is tinted by that agent's current work state, so you scan one list instead of tabbing through panes.")],-1)),d(s,{path:"readme/sessions-crop.png",caption:"Demo session rows tinted by work state; the bracketed [ready] means the session process is up, and the text after it is the reason sent with the state."}),e[2]||(e[2]=h('<h2 id="The-five-states" tabindex="-1">The five states <a class="header-anchor" href="#The-five-states" aria-label="Permalink to &quot;The five states {#The-five-states}&quot;">​</a></h2><p>The colours are the four Julia brand colours plus gray — the same palette as the helm in the logo.</p><table><thead><tr><th>Colour</th><th>State</th><th>Meaning</th><th>What to do</th></tr></thead><tbody><tr><td><span class="sot-state working"></span>green</td><td><strong>working</strong></td><td>a turn is running</td><td>nothing; let it work</td></tr><tr><td><span class="sot-state question"></span>red</td><td><strong>blocked</strong></td><td>waiting for your answer: the agent stopped with a question for you</td><td>answer it; typing into the session clears the red</td></tr><tr><td><span class="sot-state waiting"></span>purple</td><td><strong>waiting</strong></td><td>the agent handed off to a peer or a long job and is waiting on the result</td><td>nothing yet; it resumes on its own</td></tr><tr><td><span class="sot-state done"></span>blue</td><td><strong>done</strong></td><td>a turn you started has finished and you have not looked at it</td><td>read the result</td></tr><tr><td><span class="sot-state idle"></span>gray</td><td><strong>idle</strong></td><td>nothing running, nothing pending</td><td>nothing</td></tr></tbody></table><p>One marker sits outside the five states. When an agent opens a result in your preview pane from a session you are not viewing, that session&#39;s row turns bright white with a leading <code>●</code> until you switch to it. The bottom strip orders the rows on each host red, white, blue, green, purple, then gray, so what needs you comes first.</p><p>A <code>working</code> stamp that is not refreshed for a while is dimmed as stale, so a session that died mid-turn does not look busy forever.</p><h2 id="Where-the-colours-come-from" tabindex="-1">Where the colours come from <a class="header-anchor" href="#Where-the-colours-come-from" aria-label="Permalink to &quot;Where the colours come from {#Where-the-colours-come-from}&quot;">​</a></h2><p>A row&#39;s state is not a single value the agent sets; it is a small set of <strong>facts</strong> reduced by priority:</p><ul><li><p>hook <strong>events</strong> mark each turn&#39;s start and end (and who started it — you, or a message from another agent);</p></li><li><p>the agent&#39;s own <strong>declarations</strong> — <code>working</code>, <code>blocked &quot;question&quot;</code>, <code>waiting &quot;on what&quot;</code>, <code>done</code>, <code>idle</code> — set or clear a question, a wait or a done flag. <code>waiting</code> clears an open question (it says nothing needs you), and a <code>blocked</code> or <code>waiting</code> with no text, and none of its own already on the row, is refused.</p></li></ul><p>The display picks the highest-priority fact that holds: a dialog that waits on you is <strong>red</strong>, even while its turn runs; an open question with no turn running is <strong>red</strong>; otherwise a running turn is <strong>green</strong>; otherwise a wait is <strong>purple</strong>; otherwise an unread result is <strong>blue</strong>; otherwise <strong>gray</strong>. So red always wins, and typing into a session (which starts a turn you own) clears both red and blue. A Codex session&#39;s permission request raises the dialog. For a Claude Code session, which sends no event when a dialog shows, the backend reads the session&#39;s screen every five seconds, on every system, whether a turn runs or not: a background agent&#39;s permission prompt after the session&#39;s turn has ended reads red too, and so does a menu you open (<code>/model</code>, <code>/resume</code>) until it closes.</p><p>These facts live in the comm registry, next to each session&#39;s handle, which is why another agent — and every frontend attached to the backend — sees the same colour you do. The declarations are sent with <code>comm-status.sh</code>; see <a href="./comm">The comm relay</a>.</p><p>The per-entity <em>provenance</em> colours (who edited this function, is it accepted) are a separate, not-yet-built layer: see <a href="./../guide/color-coding">Provenance colours (design)</a>.</p>',11))])}const k=n(l,[["render",c]]);export{y as __pageData,k as default};
